def drive(me, enemy, arena):
    if me.airborne or me.righting or me.held or me.lifted:
        return (0.0, 0.0)
    if not me.can_drive:
        return (0.0, 0.0)
    if me.inverted and not me.invertible:
        return (0.0, 0.0)

    r = hypot(me.x, me.y)
    if r > arena.radius - 0.7:
        angle = bearing_to(0.0, 0.0)
        base = 0.6
    else:
        angle = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        rad = 0.22
        wf = me.weapons.get("front")
        if wf is not None:
            rad = wf.get("radius", 0.22)
        desired = me.length / 2.0 + min(enemy.length, enemy.width) / 2.0 + rad + 0.05
        if d > desired + 0.25:
            base = 1.0
        elif d < desired - 0.25:
            base = 0.5
        else:
            base = 0.7

    if angle > 90.0:
        angle = 90.0
    if angle < -90.0:
        angle = -90.0

    steer = 0.8 * angle / 90.0
    left = base - steer
    right = base + steer

    if left > 1.0:
        left = 1.0
    if left < -1.0:
        left = -1.0
    if right > 1.0:
        right = 1.0
    if right < -1.0:
        right = -1.0

    return (left, right)

def weapons(me, enemy, arena):
    cmds = []

    if (me.inverted or me.on_side) and not me.airborne and not me.righting:
        if me.battery_wh > 0 and me.battery_health > 0:
            can_sr = False
            wb = me.weapons.get("back")
            if wb is not None and wb.get("type") == "lifter" and wb.get("health", 0) > 0:
                can_sr = True
            wt = me.weapons.get("top")
            if not can_sr and wt is not None and wt.get("type") == "hammer" and wt.get("health", 0) > 0:
                can_sr = True
            if can_sr:
                cmds.append(self_right())

    if not cmds:
        wf = me.weapons.get("front")
        if wf is not None and wf.get("type") == "spinner" and wf.get("health", 0) > 0:
            if not me.airborne and not me.righting and not me.on_side:
                if not (me.inverted and not me.invertible):
                    if me.battery_wh > 0 and me.battery_health > 0:
                        cmds.append(spin("front", wf.get("max_rpm", 4800)))

    if cmds:
        return cmds
    return None

