        return None

    temp = wf.get("temperature", 25.0)
    rpm = wf.get("rpm", 0.0)
    if rpm < 0.0:
        rpm = -rpm
    max_rpm = wf.get("max_rpm", 2600.0)

    if temp > 170.0:
        target = 0.0
    elif temp > 155.0:
        target = rpm
        if target > max_rpm:
            target = max_rpm
    else:
        target = max_rpm

    return spin("front", target)

